//! CommP vector tests
//! (agaisnt Go's testdata vectors + full size-boundary coverage)
//!
//! Run with:
//!   cargo test --release commp_vectors
//!
//! Two strategies:
//!   1. testdata files (zero.txt, 0xCC.txt) - ground truth from Lotus ClientCalcCommP
//!      (gen.sh 7 10)
//!
//!   2. full_sizes - 118 payload sizes from 96 bytes to 1 GiB
//!      generated by gen.sh (exp 7..30), 5 payload sizes per exponent
//!      example for exp=7 (one quad = 127 payload -> 128 padded):
//!
//!       1) 96   3/4 of 2^7
//!       2) 126  one quad minus 1 byte (last quad not full)
//!       3) 127  exactly fills one quad
//!       4) 128  overflows into second quad
//!       5) 128  2^exp itself
//!
//!      for each exponent, N = 2^exp / 128 quads:
//!        3 × 2^exp / 4       midway
//!        N × 127 - 1         one byte short of N quads snug fit
//!        N × 127             exactly fills N quads
//!        N × 127 + 1         overflows into quad N+1
//!        2^exp               the power itself
//!
//!      these are raw payload sizes, commp() test helper handles odd node counts
//!      NOTE: asm kernels only see even pairs, always
//!
//!      scalar vs SIMD must agree on every size for testing purposes

use crate::lib_tests::{commp, commp_scalar};

fn max_test_size() -> usize {
    match std::env::var("MAX_TEST_SIZE") {
        Ok(v) => v.parse().unwrap_or(usize::MAX),
        Err(_) => usize::MAX,
    }
}

struct TestVector {
    payload_size: usize,
    expected_commp: [u8; 32],
}

// parse testdata CSV: payload_size,piece_size,base32_cid
// piece_size is ignored (we compute it), CID is decoded to raw 32-byte commP
fn parse_vectors(path: &str) -> Vec<TestVector> {
    let max = max_test_size();

    let contents = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("cannot read {path}: {e}"));

    contents.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|line| {
            let parts: Vec<&str> = line.splitn(3, ',').collect();

            // wasm32 usize is 32-bit - payload sizes > 4GB overflow
            // parse as u64 first, skip oversized entries (caught by .filter below)
            let payload_size: u64 = parts[0].trim().parse().unwrap();
            if payload_size > max as u64 { return TestVector { payload_size: usize::MAX, expected_commp: [0; 32] }; }
            let payload_size = payload_size as usize;
            let cid_str = parts[2].trim();

            // CID format: 'b' multibase prefix + lowercase base32 + varint header + 32 byte commP
            let decoded = base32::decode(
                base32::Alphabet::RFC4648 { padding: false },
                &cid_str[1..].to_ascii_uppercase(),
            ).unwrap_or_else(|| panic!("base32 decode failed: {cid_str}"));

            let mut expected = [0u8; 32];
            expected.copy_from_slice(&decoded[decoded.len() - 32..]);

            TestVector { payload_size, expected_commp: expected }
        })
        .filter(|v| v.payload_size <= max)
        .collect()
}

fn testdata(name: &str) -> String {
    // TODO: remove this when sure relative dir works everywhere
    // let manifest = env!("CARGO_MANIFEST_DIR");
    // format!("{manifest}/testdata/{name}")
    format!("testdata/{name}")
}

fn zero_input(n: usize) -> Vec<u8> { vec![0u8; n] }
fn cc_input(n: usize)   -> Vec<u8> { vec![0xCCu8; n] }

// 5 payload sizes per exponent:
//   [3/4]  [N×127 - 1]  [N×127]  [N×127 + 1]  [2^exp]
//     |        |           |          |          |
//   mid      last byte   exactly  first byte   the power
//   range    of quad N   N quads  of quad N+1  itself
//
// example exp=8, N=2 quads (2 × 127 = 254 payload bytes):
//   192      253          254        255          256
//     |        |           |          |
//   fits 2   fits 2      fits 2     needs 3
//   quads    quads       quads      quads <- tree grows here
const TEST_SIZES: &[usize] = &[
    // exp=7: 2^7=128, 1 quad tipping at 127 (quad count flips from 1 -> 2)
    96, 126, 127, 128,/*, 128 (deduped) */
    // exp=8: 2^8=256, 2 quads tipping at 254 (quad count flips from 2 -> 3)
    192, 253, 254, 255, 256,
    // exp=9: 2^9=512, 4 quads tipping at 508 (quad count flips from 4 -> 5)
    384, 507, 508, 509, 512,
    // exp=10: 2^10=1024, 8 quads tipping at 1016 (quad count flips from 8 -> 9)
    768, 1015, 1016, 1017, 1024,
    // exp=11
    1536, 2031, 2032, 2033, 2048,
    // exp=12
    3072, 4063, 4064, 4065, 4096,
    // exp=13
    6144, 8127, 8128, 8129, 8192,
    // exp=14
    12288, 16255, 16256, 16257, 16384,
    // exp=15
    24576, 32511, 32512, 32513, 32768,
    // exp=16
    49152, 65023, 65024, 65025, 65536,
    // exp=17
    98304, 130047, 130048, 130049, 131072,
    // exp=18
    196608, 260095, 260096, 260097, 262144,
    // exp=19
    393216, 520191, 520192, 520193, 524288,
    // exp=20
    786432, 1040383, 1040384, 1040385, 1048576,
    // exp=21
    1572864, 2080767, 2080768, 2080769, 2097152,
    // exp=22
    3145728, 4161535, 4161536, 4161537, 4194304,
    // exp=23
    6291456, 8323071, 8323072, 8323073, 8388608,
    // exp=24
    12582912, 16646143, 16646144, 16646145, 16777216,
    // exp=25
    25165824, 33292287, 33292288, 33292289, 33554432,
    // exp=26
    50331648, 66584575, 66584576, 66584577, 67108864,
    // exp=27
    100663296, 133169151, 133169152, 133169153, 134217728,
    // exp=28
    201326592, 266338303, 266338304, 266338305, 268435456,
    // exp=29
    402653184, 532676607, 532676608, 532676609, 536870912,
    // exp=30
    805306368, 1065353215, 1065353216, 1065353217, 1073741824,
];

// load vectors from testdata
//    run commp() + commp_scalar() on each
//    compare against ground truth
fn run_vectors(file: &str, gen: impl Fn(usize) -> Vec<u8>) {
    let path = testdata(file);
    let vectors = parse_vectors(&path);
    assert!(!vectors.is_empty(), "no vectors loaded from {path}");

    let mut failures = 0usize;
    for v in &vectors {
        let input = gen(v.payload_size);

        // SIMD (dispatched)
        let simd = commp(&input).unwrap();

        // scalar
        let scalar = commp_scalar(&input).unwrap();

        if simd != v.expected_commp {
            eprintln!("FAIL payload={}: simd   {}", v.payload_size, hex::encode(simd));
            eprintln!("                 want   {}", hex::encode(v.expected_commp));
            failures += 1;
        }
        if scalar != v.expected_commp {
            eprintln!("FAIL payload={}: scalar {}", v.payload_size, hex::encode(scalar));
            eprintln!("                 want   {}", hex::encode(v.expected_commp));
            failures += 1;
        }
        if simd != scalar {
            eprintln!("FAIL payload={}: simd != scalar", v.payload_size);
            failures += 1;
        }
    }
    assert_eq!(failures, 0, "{failures} vector(s) failed");
}

// run commp() (SIMD dispatch) and commp_scalar() on every size, compare
fn run_full_sizes(gen: impl Fn(usize) -> Vec<u8>) {
    let max = max_test_size();
    let mut failures = 0usize;
    for &size in TEST_SIZES {
        if size > max { continue; }

        let input = gen(size);
        let simd = commp(&input);
        let scalar = commp_scalar(&input);

        match (&simd, &scalar) {
            (Ok(s), Ok(r)) if s == r => {
                eprintln!("=== PASS  TestCommP/{size}");
            }
            (Ok(s), Ok(r)) => {
                eprintln!("=== FAIL  TestCommP/{size}: simd != scalar");
                eprintln!("  simd:   {}", hex::encode(s));
                eprintln!("  scalar: {}", hex::encode(r));
                failures += 1;
            }
            _ => {
                eprintln!("=== FAIL  TestCommP/{size}: simd={simd:?} scalar={scalar:?}");
                failures += 1;
            }
        }
    }
    assert_eq!(failures, 0, "{failures} size(s) failed");
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
#[test]
fn vectors_zero() { run_vectors("zero.txt", zero_input); }

#[test]
fn vectors_0xcc() { run_vectors("0xCC.txt", cc_input); }

#[test]
fn full_sizes_zero() { run_full_sizes(zero_input); }

#[test]
fn full_sizes_0xcc() { run_full_sizes(cc_input); }

fn random_input(n: usize) -> Vec<u8> {
    use std::io::Read;
    let path = testdata("random_1337.bin");
    let mut f = std::fs::File::open(&path)
        .unwrap_or_else(|e| panic!("cannot open {path}: {e}"));

    let mut buf = vec![0u8; n];
    f.read_exact(&mut buf)
        .unwrap_or_else(|e| panic!("cannot read {n} bytes from {path}: {e}"));
    buf
}

#[test]
fn vectors_random() { run_vectors("random.txt", random_input); }